"""Veridex updater. Put this file in the veridex folder (next to README.md) and run:  python update_15.py"""
import base64, os
HERE = os.path.dirname(os.path.abspath(__file__))
FILES = {'core/env.py': '', 'api/main.py': '', 'bot/telegram_bot.py': '', '.env.example': 'IyBDb3B5IHRoaXMgZmlsZSB0byAiLmVudiIgKHNhbWUgZm9sZGVyKSBhbmQgZmlsbCBpbiB5b3VyIG93biBrZXlzLiBORVZFUiBjb21taXQgLmVudi4KVEVMRUdSQU1fQk9UX1RPS0VOPQpLSEFZQV9BUElfS0VZPQpHUk9RX0FQSV9LRVk9ClBBWVNUQUNLX1NFQ1JFVF9LRVk9Cg==', '.gitignore': 'LmVudgoqLmRiCmF1ZGlvX2NhY2hlLwpfX3B5Y2FjaGVfXy8KKi5weWMKLnZlbnYvCnZlbnYvCg==', 'start_all.ps1': ''}
for rel, b in FILES.items():
    p = os.path.join(HERE, *rel.split("/"))
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "wb").write(base64.b64decode(b))
    print("updated", rel)
print("Done. Now run: pip install -r requirements.txt   then restart the bot.")
